         return 1;
     }
     lines.get(idx).map_or(1, |line| {
-        wrap_spans_hanging(&line.spans, content_start, viewport_width).len()
+        wrap_unified_row(&line.spans, content_start, flow_start, viewport_width).len()
     })
 }

